const src = $input.first().json;
const body = src.body ?? src;

const exterior = Array.isArray(body.exterior_images) ? body.exterior_images.filter(Boolean) : [];
const interior = Array.isArray(body.interior_images) ? body.interior_images.filter(Boolean) : [];

if (!body.car_name) {
  throw new Error('car_name is required');
}

if (exterior.length === 0) {
  throw new Error('exterior_images is required');
}

if (interior.length === 0) {
  throw new Error('interior_images is required');
}

const runId = (typeof body.run_id === 'string' && body.run_id.trim())
  ? body.run_id.trim()
  : `wf003_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;

const workflowCode = (typeof body.workflow_code === 'string' && body.workflow_code.trim())
  ? body.workflow_code.trim()
  : 'WF-003';

const clientRequestId = (typeof body.client_request_id === 'string' && body.client_request_id.trim())
  ? body.client_request_id.trim()
  : runId;

const userId = typeof body.user_id === 'string' ? body.user_id.trim() : '';
const feishuAppId = typeof body.feishu_app_id === 'string' ? body.feishu_app_id.trim() : '';
const feishuId = typeof body.feishu_id === 'string' ? body.feishu_id.trim() : '';

if (!feishuAppId) {
  throw new Error('feishu_app_id is required');
}

if (!feishuId) {
  throw new Error('feishu_id is required');
}

const count = interior.length;
let interiorGroups = [];
if (count <= 3) {
  interiorGroups = [interior];
} else if (count === 4) {
  interiorGroups = [interior.slice(0, 2), interior.slice(2, 4)];
} else {
  interiorGroups = [interior.slice(0, 3), interior.slice(3, 5)];
}

const expectedTasks = exterior.length + interiorGroups.length;

const fallbackCallbackUrl = 'https://gzl.wikigood.top/api/v1/workflow-runs/wf003-callback';
const fallbackCallbackToken = 'wf003_local_callback_9f3c7a1d';
const rawCallbackUrl = typeof body.callback_url === 'string' ? body.callback_url.trim() : '';
let normalizedCallbackUrl = rawCallbackUrl || fallbackCallbackUrl;
const isHttpUrl = /^https?:\/\//i.test(normalizedCallbackUrl);
const isExpectedCallbackPath = /\/api\/v1\/workflow-runs\/wf003-callback$/i.test(normalizedCallbackUrl);
if (!isHttpUrl || !isExpectedCallbackPath) {
  normalizedCallbackUrl = fallbackCallbackUrl;
}
const normalizedCallbackToken = typeof body.callback_token === 'string' && body.callback_token.trim()
  ? body.callback_token.trim()
  : fallbackCallbackToken;

return [{
  json: {
    submissionId: runId,
    run_id: runId,
    workflow_code: workflowCode,
    client_request_id: clientRequestId,
    user_id: userId,
    callback_url: normalizedCallbackUrl,
    callback_token: normalizedCallbackToken,
    car_name: body.car_name,
    logo: body.logo || '',
    token: body.token || '',
    source: body.source || '',
    submitted_at: body.submitted_at || new Date().toISOString(),
    feishu_app_id: feishuAppId,
    feishu_id: feishuId,
    exterior_images: exterior,
    interior_images: interior,
    interior_groups: interiorGroups,
    expectedTasks
  }
}];

const input = $input.first().json;
const tasks = [];

(input.exterior_images || []).forEach((url, index) => {
  tasks.push({
    json: {
      submissionId: input.submissionId,
      run_id: input.run_id,
      workflow_code: input.workflow_code,
      client_request_id: input.client_request_id,
      user_id: input.user_id || '',
      callback_url: input.callback_url,
      callback_token: input.callback_token,
      car_name: input.car_name,
      logo: input.logo,
      feishu_app_id: input.feishu_app_id || '',
      feishu_id: input.feishu_id || '',
      expectedTasks: input.expectedTasks,
      type: 'exterior',
      index: index + 1,
      imageUrl: url
    }
  });
});

(input.interior_groups || []).forEach((group, index) => {
  tasks.push({
    json: {
      submissionId: input.submissionId,
      run_id: input.run_id,
      workflow_code: input.workflow_code,
      client_request_id: input.client_request_id,
      user_id: input.user_id || '',
      callback_url: input.callback_url,
      callback_token: input.callback_token,
      car_name: input.car_name,
      logo: input.logo,
      feishu_app_id: input.feishu_app_id || '',
      feishu_id: input.feishu_id || '',
      expectedTasks: input.expectedTasks,
      type: 'interior',
      groupIndex: index + 1,
      imageUrls: group
    }
  });
});

return tasks;

const item = $json;
const callbackUrl = 'https://n8n.deepsix.store/webhook/wf003-kie-callback-123';

const common = {
  submissionId: item.submissionId,
  run_id: item.run_id || item.submissionId,
  workflow_code: item.workflow_code || 'WF-003',
  client_request_id: item.client_request_id || '',
  user_id: item.user_id || '',
  callback_url: item.callback_url || '',
  callback_token: item.callback_token || '',
  car_name: item.car_name || '',
  logo: item.logo || '',
  feishu_app_id: item.feishu_app_id || '',
  feishu_id: item.feishu_id || '',
  expectedTasks: item.expectedTasks || 0,
  type: item.type
};

if (item.type === 'exterior') {
  return [{
    json: {
      ...common,
      index: item.index,
      imageUrl: item.imageUrl,
      requestBody: {
        model: 'nano-banana-2',
        callBackUrl: callbackUrl,
        input: {
          prompt: 'Generate one output image for each uploaded car exterior reference image. If multiple exterior reference images are provided, every single uploaded exterior image must be processed, and none of them can be skipped or omitted. Maintain a strict one-to-one mapping: one reference image = one generated image. Keep the car body completely unchanged in each image, including body shape, proportions, paint color, trim, wheels, headlights, taillights, windows, mirrors, and all exterior design details. Do not alter the vehicle appearance in any way. Change the scene to a premium pure white luxury automotive showroom with a seamless curved white backdrop, polished white reflective floor, subtle architectural layering, soft ambient reflections, hidden linear ceiling lights, diffused studio lighting, and a clean high-end exhibition atmosphere. The showroom should feel elegant, modern, minimal, premium, and suitable for commercial car advertising, while still keeping the background clean and not distracting from the car. Do not alter the style of the product logo. Add the logo from the second reference image to the license plate area. Also add the same logo in the top-left corner of each generated image. Do not generate multiple angles from one reference. Generate exactly one result for each uploaded reference image. Preserve the original viewing angle and composition of each reference image. Photorealistic, professional automotive photography, ultra-detailed, premium commercial quality. Output size: 1024x1024.',
          image_input: [item.imageUrl, item.logo],
          aspect_ratio: '1:1',
          resolution: '1K',
          output_format: 'jpg'
        }
      }
    }
  }];
}

return [{
  json: {
    ...common,
    groupIndex: item.groupIndex,
    imageUrls: item.imageUrls,
    requestBody: {
      model: 'nano-banana-2',
      callBackUrl: callbackUrl,
      input: {
        prompt: 'Strictly use the uploaded interior reference images to create collage outputs. Do not change the original camera angle. Do not generate new scenes. Do not crop one image into multiple close-up panels. Each panel must correspond to a different uploaded original image. Each uploaded image can be used only once, and all uploaded images must be used. If 1 to 3 images are uploaded, generate 1 collage. If 4 images are uploaded, generate 2 collages in a 2 plus 2 grouping. If 5 images are uploaded, generate 2 collages in a 3 plus 2 grouping. Use a clean and tidy grid or side-by-side layout with clear separation between panels. Keep the original images complete and sharp, without stretching or overlap. Professional automotive interior collage style. Output size: 1024x1024.',
        image_input: item.imageUrls,
        aspect_ratio: '1:1',
        resolution: '1K',
        output_format: 'jpg'
      }
    }
  }
}];

const requestMeta = $('Prepare Kie Task Payload').item.json;
const createResp = $json || {};
const taskId = createResp?.data?.taskId || null;

if (!taskId) {
  throw new Error('Kie createTask returned no taskId');
}

return [{
  json: {
    submissionId: requestMeta.submissionId,
    run_id: requestMeta.run_id || requestMeta.submissionId,
    workflow_code: requestMeta.workflow_code || 'WF-003',
    client_request_id: requestMeta.client_request_id || '',
    user_id: requestMeta.user_id || '',
    callback_url: requestMeta.callback_url || '',
    callback_token: requestMeta.callback_token || '',
    car_name: requestMeta.car_name,
    logo: requestMeta.logo || '',
    feishu_app_id: requestMeta.feishu_app_id || '',
    feishu_id: requestMeta.feishu_id || '',
    expectedTasks: requestMeta.expectedTasks || 0,
    taskId,
    type: requestMeta.type,
    index: requestMeta.index || null,
    groupIndex: requestMeta.groupIndex || null,
    imageUrl: requestMeta.imageUrl || null,
    imageUrls: requestMeta.imageUrls || []
  }
}];

const source = $('Normalize Submission').first().json;
return [{
  json: {
    ok: true,
    message: 'Tasks submitted to Kie. Waiting for callbacks.',
    submissionId: source.submissionId,
    expectedTasks: source.expectedTasks,
    exteriorCount: (source.exterior_images || []).length,
    interiorCount: (source.interior_images || []).length
  }
}];

const src = $input.first().json;
const body = src.body ?? src;
const data = body.data || {};

let resultJson = {};
try {
  if (typeof data.resultJson === 'string') {
    resultJson = JSON.parse(data.resultJson);
  } else if (data.resultJson && typeof data.resultJson === 'object') {
    resultJson = data.resultJson;
  }
} catch (error) {
  resultJson = {};
}

const resultUrls = Array.isArray(resultJson.resultUrls) ? resultJson.resultUrls : [];
const resultUrl = resultUrls[0] || body.resultUrl || data.resultUrl || null;
const taskId = data.taskId || body.taskId || body.id || null;
const rawState = String(data.state || body.state || '').toLowerCase();
const failCode = data.failCode || body.failCode || null;
const failMsg = data.failMsg || body.failMsg || body.msg || null;

if (!taskId) {
  throw new Error('Callback contains no taskId');
}

let state = rawState || 'unknown';
if (resultUrl) {
  state = 'success';
} else if (['failed', 'fail', 'error'].includes(state)) {
  state = 'failed';
}

return [{
  json: {
    taskId,
    state,
    rawState,
    resultUrl,
    failCode,
    failMsg,
    body
  }
}];

const input = $input.first().json || {};
const exteriorImages = Array.isArray(input.exteriorImages) ? input.exteriorImages : [];
const interiorImages = Array.isArray(input.interiorImages) ? input.interiorImages : [];
const groupName = `wf003_group_${Date.now()}`;
const vehicleId = `car_${Date.now()}`;
const feishuAppId = (input.feishu_app_id || '').trim();
const feishuId = (input.feishu_id || '').trim();
const items = [];

if (!feishuAppId) {
  throw new Error('strict_mode: feishu_app_id is required');
}

if (!feishuId) {
  throw new Error('strict_mode: feishu_id is required');
}

if (exteriorImages.length === 0 && interiorImages.length === 0) {
  throw new Error('strict_mode: no successful images to write into Feishu');
}

exteriorImages.forEach((item, index) => {
  const url = item.imageUrl || '';
  if (!url) return;
  items.push({
    json: {
      submissionId: input.submissionId,
      groupName,
      vehicleId,
      feishu_app_id: feishuAppId,
      feishu_id: feishuId,
      category: 'exterior',
      order: index + 1,
      sourceUrl: url,
      fileName: `exterior_${index + 1}.jpg`
    }
  });
});

interiorImages.forEach((item, index) => {
  const url = item.imageUrl || '';
  if (!url) return;
  items.push({
    json: {
      submissionId: input.submissionId,
      groupName,
      vehicleId,
      feishu_app_id: feishuAppId,
      feishu_id: feishuId,
      category: 'interior',
      order: index + 1,
      sourceUrl: url,
      fileName: `interior_${index + 1}.jpg`
    }
  });
});

if (items.length === 0) {
  throw new Error('strict_mode: no valid upload items for Feishu');
}

return items;

return [{
  json: {
    submissionId: $('Loop Upload Items').item.json.submissionId,
    groupName: $('Loop Upload Items').item.json.groupName,
    vehicleId: $('Loop Upload Items').item.json.vehicleId,
    feishu_app_id: $('Loop Upload Items').item.json.feishu_app_id,
    feishu_id: $('Loop Upload Items').item.json.feishu_id,
    category: $('Loop Upload Items').item.json.category,
    order: $('Loop Upload Items').item.json.order,
    fileName: $('Loop Upload Items').item.json.fileName,
    fileToken: $json.data?.file_token || $json.file_token || ''
  }
}];

const items = $input.all();
const result = {
  submissionId: items[0]?.json?.submissionId || '',
  groupName: items[0]?.json?.groupName || `wf003_group_${Date.now()}`,
  vehicleId: items[0]?.json?.vehicleId || `car_${Date.now()}`,
  feishu_app_id: items[0]?.json?.feishu_app_id || '',
  feishu_id: items[0]?.json?.feishu_id || '',
  exteriorAttachments: [],
  interiorAttachments: []
};

for (const item of items) {
  const token = item.json.fileToken;
  if (!token) continue;

  const attachment = { file_token: token };

  if (item.json.category === 'exterior') {
    result.exteriorAttachments.push(attachment);
  } else if (item.json.category === 'interior') {
    result.interiorAttachments.push(attachment);
  }
}

return [{ json: result }];

